import math, random

def margin(p, n):
    return 1.96 * math.sqrt(p * (1 - p) / n)

for n in (100, 400, 1000, 2500, 10000):
    print(f"n={n:6d}: +/-{100 * margin(0.5, n):.1f} points")

random.seed(36)                                                 # 1,000 polls of 1,000 people, true support 52%
inside = 0
for _ in range(1000):
    p_hat = sum(random.random() < 0.52 for _ in range(1000)) / 1000
    inside += abs(p_hat - 0.52) <= margin(p_hat, 1000)
print(inside / 1000, "of the polls' intervals contained the truth")       # about 0.95
